VALUES (
    '019e4eae-b4c7-7fd3-8314-b263a237f60a',
    '019e4eae-720c-7464-b6c1-7dcc80923643',
    'Suy ngẫm về sự suy tàn của một triều đại huy hoàng',
    'Nhìn lại lịch sử thời Lý, không khỏi chạnh lòng khi thấy một triều đại từng rực rỡ dưới thời các vua Thái Tổ, Thái Tông, Thánh Tông và Nhân Tông lại dần rơi vào cảnh rối ren. Từ những vị vua anh minh, biết thương dân, trọng việc nông tang, đến thời kỳ những ông vua lên ngôi khi còn quá nhỏ, quyền bính rơi vào tay ngoại thích và hoạn quan. Những kẻ như Đỗ Anh Vũ, cậy thế lộng hành, đẩy triều đình vào cảnh nghi kỵ, sát hại lẫn nhau. Phải chăng sự hưng thịnh của một quốc gia luôn gắn liền với sự minh triết của người đứng đầu? Khi kỷ cương phép nước bị buông lỏng, liệu đó có phải là điểm khởi đầu cho một sự thay thế tất yếu của lịch sử?',
    'PUBLISHED',
    0.6161,
    0,
    0,
    0,
    0,
    '2026-04-23 23:53:09.000',
    '2026-05-15 23:28:09.000',
    NULL
);


INSERT INTO posts (
    id,
    author_id,
