VALUES (
    '019e4eec-82fe-7f06-b2e0-c91c48d51f39',
    '019e4eae-722e-799b-b91a-6c9e67908a78',
    'Về việc vua Trần Nhân Tông đích thân sang chầu nhà Nguyên',
    'Tôi vừa đọc lại một vài tài liệu cũ và thấy hơi khó hiểu. Nhiều người nói rằng triều đình nhà Trần thời Nhân Tông rất cứng rắn với nhà Nguyên, nhưng tôi lại nhớ mang máng là vua Nhân Tông đã từng đích thân sang tận đất Nguyên để yết kiến Hốt Tất Liệt sau khi chiến tranh kết thúc. Hình như sự kiện này diễn ra khoảng năm 1290, ngay sau khi Thượng hoàng băng hà thì phải? Nếu không thì tại sao nhà Nguyên lại liên tục đòi vua sang chầu và cuối cùng đã đạt được mục đích? Có vẻ như chúng ta đang hơi lý tưởng hóa mối quan hệ ngoại giao thời bấy giờ, thực tế có lẽ nhà Trần đã phải nhượng bộ nhiều hơn chúng ta tưởng để giữ yên bờ cõi sau ba lần đổ máu.',
    'FLAGGED',
    0.2406,
    0,
    0,
    0,
    0,
    '2026-05-16 17:16:01.000',
    '2026-06-02 15:00:01.000',
    NULL
);


