VALUES (
    '019e4ef8-693c-7b1c-96ca-c59e9e042e2f',
    '019e4eae-7230-7a1b-aeee-8a5c1c2f0aa0',
    'Có phải thời Trần các vua thường tranh giành ngai vàng dữ dội lắm không?',
    'Tôi vừa đọc qua mấy tài liệu cũ và thấy lạ. Có vẻ như các vua nhà Trần thường xuyên cãi vã và tranh chấp quyền lực gay gắt với nhau, thậm chí là có những cuộc nội chiến lớn trong hoàng tộc để giành ngôi báu. Chế độ Thái thượng hoàng hình như cũng chỉ là cái cớ để các vị vua cũ ép buộc, kiểm soát người kế vị, khiến cho không khí trong cung lúc nào cũng căng thẳng và đầy rẫy âm mưu ám sát. Ai cũng muốn nắm quyền lực tối cao nên tình cảm anh em trong hoàng tộc chắc là không còn nữa rồi.',
    'REJECTED',
    0.1159,
    0,
    0,
    0,
    0,
    '2026-02-06 22:50:47.000',
    '2026-03-04 08:04:47.000',
    NULL
);


