VALUES (
    '019e4f03-1cc2-7158-8197-2bbfe620a0d0',
    '019e4eae-7220-7480-9d88-eff78ded1e54',
    'Suy ngẫm về tính xác thực của các bộ binh thư cổ',
    'Gần đây tôi có đọc lại những tài liệu về nền quân sự thời Trần và bắt đầu tự hỏi về tính xác thực của những gì chúng ta gọi là ''Binh thư yếu lược''. Việc ca ngợi Hưng Đạo Vương là người đặt nền móng cho khoa học quân sự Việt Nam là điều không thể phủ nhận dựa trên những chiến công hiển hách. Tuy nhiên, liệu chúng ta có đang lý tưởng hóa quá mức tầm ảnh hưởng của các bộ binh pháp cổ đại trong bối cảnh chiến trận thực tế tại Đại Việt hay không? Nhiều sử liệu nhắc đến việc ông vận dụng sáng tạo tư tưởng của Tôn Tử, Ngô Khởi hay Khổng Minh, nhưng liệu đó là sự chắt lọc thực sự hay chỉ là cách các sử gia đời sau gán ghép những tư tưởng ''văn minh'' vào để nâng tầm vị thế của các bậc tiền nhân? Hơn nữa, việc thất truyền nhiều bộ sử và binh thư gốc khiến mọi nhận định hiện nay phần lớn dựa trên những ghi chép tản mát hoặc lời bình từ các bộ sách đời sau như ''Đại Việt sử ký toàn thư''. Phải chăng chúng ta đang nhìn lịch sử qua một lăng kính đã được chỉnh sửa để phù hợp với tư tưởng của những thời đại sau này? Đây là một nghi vấn cần được xem xét kỹ lưỡng hơn trước khi khẳng định chắc chắn về tính nguyên bản của các văn bản quân sự thời đó.',
    'DRAFT',
    0.5141,
    0,
    0,
    0,
    0,
    '2026-04-27 02:47:32.000',
    '2026-04-27 14:38:32.000',
    NULL
);


INSERT INTO posts (
